//! Aero glass primitives implemented as real surface composition.
//!
//! These helpers are intentionally separate from the static theme tokens:
//! glass is generated by blurring and tinting the backdrop, while shadows and
//! rounded windows are rendered as alpha masks on the output surface.

use crate::graphics::surface::lerp_color;
use crate::graphics::Rect;
use crate::graphics::Surface;

fn graphics_rect(rect: Rect) -> crate::graphics::Rect {
    crate::graphics::Rect::new(rect.x, rect.y, rect.width, rect.height)
}

pub const GLASS_BLUR_RADIUS: u32 = 8;
pub const GLASS_TINT_STRENGTH: u32 = 96;
pub const WINDOW_GLASS: u32 = 0xE845_80C4;
pub const WINDOW_BODY: u32 = 0xFFF0_F0F0;
pub const WINDOW_BORDER: u32 = 0xB300_0000;
pub const ELEMENT_BORDER: u32 = 0xFF8E_8F8F;
pub const ELEMENT_HOVER_BORDER: u32 = 0xFF3C_7FB1;
pub const ELEMENT_ACTIVE_BORDER: u32 = 0xFF6D_91AB;
pub const ELEMENT_SURFACE: u32 = 0xFFF2_F2F2;

pub fn glass_backdrop(backdrop: &Surface, tint: u32, saturation: u32) -> Surface {
    let mut glass = backdrop.clone();
    glass.box_blur(GLASS_BLUR_RADIUS);
    glass.saturate(saturation);
    glass.tint(tint, GLASS_TINT_STRENGTH);
    glass
}

pub fn blend_rect(surface: &mut Surface, bounds: Rect, color: u32) {
    surface.blend_rect(bounds, color);
}

pub fn blend_rounded_rect(surface: &mut Surface, bounds: Rect, radius: u32, color: u32) {
    surface.blend_rounded_rect(bounds, radius, color);
}

pub fn vertical_gradient(surface: &mut Surface, top: u32, bottom: u32) {
    surface.vertical_gradient(top, bottom);
}

pub fn radial_blend(
    surface: &mut Surface,
    center_x: u32,
    center_y: u32,
    diameter: u32,
    center: u32,
    edge: u32,
    center_alpha: u8,
    edge_alpha: u8,
) {
    let radius = diameter as i32 / 2;
    let left = center_x.saturating_sub(radius.max(0) as u32);
    let top = center_y.saturating_sub(radius.max(0) as u32);
    for row in 0..diameter {
        for column in 0..diameter {
            let dx = column as i32 - radius;
            let dy = row as i32 - radius;
            let distance_squared = (dx * dx + dy * dy) as u64;
            let limit = (radius.max(0) as u64).pow(2);
            if distance_squared > limit {
                continue;
            }
            let scale = if limit == 0 {
                0
            } else {
                (distance_squared * 255 / limit) as u32
            };
            let color = lerp_color(center, edge, scale);
            let alpha = ((center_alpha as u32 * (255 - scale) + edge_alpha as u32 * scale) / 255)
                .min(255) as u8;
            surface.blend_pixel(
                left + column,
                top + row,
                ((alpha as u32) << 24) | (color & 0x00FF_FFFF),
            );
        }
    }
}

pub fn glass_bar(surface: &mut Surface, bounds: Rect, wallpaper: &Surface) {
    let glass = glass_backdrop(wallpaper, 0x10_1B2B40, 96);
    let source_bounds = Rect::new(bounds.x, bounds.y, bounds.width, bounds.height);
    surface.copy_region(&glass, source_bounds, bounds.x, bounds.y);
    let highlight = Rect::new(bounds.x, bounds.y, bounds.width, 1);
    surface.blend_rect(highlight, 0xB4FF_FFFF);
    let inner = Rect::new(bounds.x, bounds.y + 1, bounds.width, 2);
    surface.blend_rect(inner, 0x34FF_FFFF);
    let bottom = Rect::new(
        bounds.x,
        bounds.y + bounds.height.saturating_sub(1) as i32,
        bounds.width,
        1,
    );
    surface.blend_rect(bottom, 0xD800_0000);
}

pub fn glass_bar_precomputed(surface: &mut Surface, bounds: Rect, glass: &Surface) {
    let source_bounds = Rect::new(bounds.x, bounds.y, bounds.width, bounds.height);
    surface.copy_region(glass, source_bounds, bounds.x, bounds.y);
    surface.blend_rect(Rect::new(bounds.x, bounds.y, bounds.width, 1), 0xB4FF_FFFF);
    surface.blend_rect(
        Rect::new(bounds.x, bounds.y + 1, bounds.width, 2),
        0x34FF_FFFF,
    );
    surface.blend_rect(
        Rect::new(
            bounds.x,
            bounds.y + bounds.height.saturating_sub(1) as i32,
            bounds.width,
            1,
        ),
        0xD800_0000,
    );
}

pub fn glass_button(surface: &mut Surface, bounds: Rect, selected: bool) {
    let fill = if selected { 0xE86B_B2E6 } else { 0x88FF_FFFF };
    surface.blend_rounded_rect(bounds, 3, fill);
    surface.blend_rect(
        Rect::new(
            bounds.x + 1,
            bounds.y + 1,
            bounds.width.saturating_sub(2),
            1,
        ),
        0x90FF_FFFF,
    );
}

pub fn taskbar_chrome(surface: &mut Surface, bounds: Rect, glass: &Surface) {
    glass_bar_precomputed(surface, bounds, glass);
    let denominator = bounds.height.saturating_sub(1).max(1) as u32;
    for row in 0..bounds.height {
        let scale = row * 255 / denominator;
        let color = if scale < 24 {
            lerp_color(0x66FF_FFFF, 0x14FF_FFFF, scale * 255 / 24)
        } else if scale < 192 {
            lerp_color(0x14FF_FFFF, 0x1A00_0000, (scale - 24) * 255 / 168)
        } else {
            lerp_color(0x1A00_0000, 0xD800_0000, (scale - 192) * 255 / 63)
        };
        surface.blend_rect(
            Rect::new(bounds.x, bounds.y + row as i32, bounds.width, 1),
            color,
        );
    }
    surface.blend_rect(Rect::new(bounds.x, bounds.y, bounds.width, 1), 0xB4FF_FFFF);
    surface.blend_rect(
        Rect::new(
            bounds.x,
            bounds.y + bounds.height.saturating_sub(1) as i32,
            bounds.width,
            1,
        ),
        0xD800_0000,
    );
}

pub fn superbar_button(surface: &mut Surface, bounds: Rect, selected: bool) {
    let denominator = bounds.height.saturating_sub(1).max(1) as u32;
    for row in 0..bounds.height {
        let scale = row * 255 / denominator;
        let color = if selected {
            if scale < 128 {
                lerp_color(0xFFB6_D9EE, 0xFFB6_D9EE, 0)
            } else {
                lerp_color(0xFF1A_6CA1, 0xFF1A_6CA1, 0)
            }
        } else if scale < 115 {
            lerp_color(0x80FF_FFFF, 0x4DFF_FFFF, scale * 255 / 115)
        } else if scale < 128 {
            lerp_color(0x4DFF_FFFF, 0x1A00_0000, (scale - 115) * 255 / 13)
        } else if scale < 192 {
            0x1A00_0000
        } else {
            lerp_color(0x1A00_0000, 0x80FF_FFFF, (scale - 192) * 255 / 63)
        };
        surface.blend_rect(
            Rect::new(bounds.x, bounds.y + row as i32, bounds.width, 1),
            color,
        );
    }
    surface.blend_rounded_rect(bounds, 3, 0x20FF_FFFF);
    surface.blend_rect(Rect::new(bounds.x, bounds.y, bounds.width, 1), 0xB4FF_FFFF);
    surface.blend_rect(
        Rect::new(
            bounds.x,
            bounds.y + bounds.height.saturating_sub(1) as i32,
            bounds.width,
            1,
        ),
        0x4D00_0000,
    );
}

pub fn horizontal_gradient(
    surface: &mut Surface,
    bounds: Rect,
    left: u32,
    middle: u32,
    right: u32,
) {
    let denominator = bounds.width.saturating_sub(1).max(1);
    let gradient = |left: u32, right: u32, scale: u32| {
        let alpha = ((left >> 24) * (255 - scale) + (right >> 24) * scale + 128) / 255;
        let color = lerp_color(left, right, scale) & 0x00FF_FFFF;
        (alpha << 24) | color
    };
    for column in 0..bounds.width {
        let scale = (column * 255) / denominator;
        let color = if scale <= 128 {
            gradient(left, middle, (scale * 2).min(255))
        } else {
            gradient(middle, right, ((scale - 128) * 2).min(255))
        };
        surface.blend_rect(
            Rect::new(bounds.x + column as i32, bounds.y, 1, bounds.height),
            color,
        );
    }
}

pub fn title_bar(surface: &mut Surface, bounds: Rect, glass: &Surface) {
    glass_bar_precomputed(surface, bounds, glass);
    horizontal_gradient(surface, bounds, 0x66FF_FFFF, 0x1A00_0000, 0x33FF_FFFF);
    let highlight_top = Rect::new(bounds.x, bounds.y, bounds.width, 1);
    surface.blend_rect(highlight_top, 0x59FF_FFFF);
    let highlight_mid = Rect::new(
        bounds.x,
        bounds.y + bounds.height as i32 * 2 / 5,
        bounds.width,
        1,
    );
    surface.blend_rect(highlight_mid, 0xB3FF_FFFF);
    let highlight_bottom = Rect::new(
        bounds.x,
        bounds.y + bounds.height as i32 - 1,
        bounds.width,
        1,
    );
    surface.blend_rect(highlight_bottom, 0x40FF_FFFF);
}

pub fn window_body(surface: &mut Surface, bounds: Rect) {
    surface.fill_rect(bounds.x, bounds.y, bounds.width, bounds.height, WINDOW_BODY);
    surface.blend_rect(
        Rect::new(bounds.x, bounds.y, bounds.width, 1),
        WINDOW_BORDER,
    );
    surface.blend_rect(
        Rect::new(
            bounds.x,
            bounds.y + bounds.height.saturating_sub(1) as i32,
            bounds.width,
            1,
        ),
        WINDOW_BORDER,
    );
    surface.blend_rect(
        Rect::new(bounds.x, bounds.y, 1, bounds.height),
        WINDOW_BORDER,
    );
    surface.blend_rect(
        Rect::new(
            bounds.x + bounds.width.saturating_sub(1) as i32,
            bounds.y,
            1,
            bounds.height,
        ),
        WINDOW_BORDER,
    );
    surface.blend_rect(Rect::new(bounds.x, bounds.y, bounds.width, 1), 0x40FF_FFFF);
}

pub fn shadow(surface: &mut Surface, bounds: Rect, radius: u32) {
    let outer = Rect::new(
        bounds.x - radius as i32,
        bounds.y - radius as i32,
        bounds.width + radius * 2,
        bounds.height + radius * 2,
    );
    surface.shadow_rect(outer, radius);
}

pub fn control_group(surface: &mut Surface, bounds: Rect, active: bool) {
    let alpha = if active { 0x33FF_FFFF } else { 0x1FFF_FFFF };
    surface.blend_rect(bounds, alpha);
    surface.blend_rect(bounds, 0x4D00_0000);
    surface.blend_rect(Rect::new(bounds.x, bounds.y, bounds.width, 1), 0xA0FF_FFFF);
    surface.blend_rect(
        Rect::new(
            bounds.x,
            bounds.y + bounds.height.saturating_sub(1) as i32,
            bounds.width,
            1,
        ),
        0x80FF_FFFF,
    );
    surface.blend_rect(Rect::new(bounds.x, bounds.y, 1, bounds.height), 0x80FF_FFFF);
    surface.blend_rect(
        Rect::new(
            bounds.x + bounds.width.saturating_sub(1) as i32,
            bounds.y,
            1,
            bounds.height,
        ),
        0x80FF_FFFF,
    );
    for offset in [29, 58] {
        let separator_x = bounds.x + offset as i32;
        surface.blend_rect(
            Rect::new(separator_x, bounds.y, 1, bounds.height),
            0x4D00_0000,
        );
    }
}

pub fn arrow_right(surface: &mut Surface, bounds: Rect, color: u32) {
    let half_height = bounds.height as f32 / 2.0;
    for row in 0..bounds.height {
        for column in 0..bounds.width {
            let ratio = column as f32 / bounds.width.saturating_sub(1).max(1) as f32;
            let distance = (row as f32 - half_height).abs();
            let coverage = if distance <= half_height * ratio - 1.0 {
                255
            } else if distance <= half_height * ratio {
                ((half_height * ratio - distance) * 255.0) as u8
            } else {
                0
            };
            if coverage != 0 {
                let alpha = ((color >> 24) as u32 * coverage as u32 / 255) as u8;
                surface.blend_pixel(
                    bounds.x.saturating_add(column as i32) as u32,
                    bounds.y.saturating_add(row as i32) as u32,
                    ((alpha as u32) << 24) | (color & 0x00FF_FFFF),
                );
            }
        }
    }
}

pub fn shadow_rect(surface: &mut Surface, bounds: Rect, radius: u32) {
    if bounds.width == 0 || bounds.height == 0 {
        return;
    }
    let mut shadow = surface.clone();
    shadow.fill_rect(bounds.x, bounds.y, bounds.width, bounds.height, 0xFF00_0000);
    shadow.box_blur(radius);
    for row in 0..surface.height() {
        for column in 0..surface.width() {
            let coverage = (shadow.pixel(column, row).unwrap_or(0) >> 24) & 0xFF;
            if coverage != 0 {
                surface.blend_pixel(column, row, coverage << 24);
            }
        }
    }
}

pub fn rounded_window(surface: &mut Surface, bounds: Rect, radius: u32, fill: u32) {
    if bounds.width == 0 || bounds.height == 0 {
        return;
    }
    let rect = graphics_rect(bounds);
    surface.rounded_rect(rect, radius, fill);
    let highlight = Rect::new(bounds.x, bounds.y, bounds.width, 1);
    surface.fill_rect(highlight.x, highlight.y, highlight.width, 1, 0xB4FF_FFFF);
}

pub fn window_border(surface: &mut Surface, bounds: Rect, radius: u32) {
    let radius = radius.min(bounds.width / 2).min(bounds.height / 2);
    let border = bounds.width.min(bounds.height) / 4;
    for index in 0..border.max(1) {
        let inset = Rect::new(
            bounds.x + index as i32,
            bounds.y + index as i32,
            bounds.width.saturating_sub(index * 2),
            bounds.height.saturating_sub(index * 2),
        );
        surface.blend_rounded_rect(inset, radius, WINDOW_BORDER);
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum WindowControlButtonKind {
    Minimize,
    Maximize,
    Close,
}

pub fn window_control_group(surface: &mut Surface, bounds: Rect, active: bool) {
    let fill = if active { 0x4DFF_FFFF } else { 0x33FF_FFFF };
    surface.blend_rounded_rect(bounds, 5, fill);
    surface.blend_rounded_rect(bounds, 5, 0x4D00_0000);
    surface.blend_rect(
        Rect::new(bounds.x + 1, bounds.y, bounds.width.saturating_sub(2), 1),
        0xB4FF_FFFF,
    );
    for offset in [29, 58] {
        let separator_x = bounds.x + offset as i32;
        surface.blend_rect(
            Rect::new(separator_x, bounds.y, 1, bounds.height),
            0x4D00_0000,
        );
    }
}

pub fn window_control_button(
    surface: &mut Surface,
    bounds: Rect,
    kind: WindowControlButtonKind,
    hovered: bool,
) {
    let denominator = bounds.height.saturating_sub(1).max(1) as u32;
    for row in 0..bounds.height {
        let scale = row * 255 / denominator;
        let color = match kind {
            WindowControlButtonKind::Minimize | WindowControlButtonKind::Maximize => {
                if hovered {
                    if scale < 128 {
                        lerp_color(0xFFB6_D9EE, 0xFFB6_D9EE, 0)
                    } else {
                        lerp_color(0xFF1A_6CA1, 0xFF1A_6CA1, 0)
                    }
                } else if scale < 115 {
                    lerp_color(0x80FF_FFFF, 0x4DFF_FFFF, scale * 255 / 115)
                } else if scale < 128 {
                    lerp_color(0x4DFF_FFFF, 0x1A00_0000, (scale - 115) * 255 / 13)
                } else if scale < 192 {
                    0x1A00_0000
                } else {
                    lerp_color(0x1A00_0000, 0x80FF_FFFF, (scale - 192) * 255 / 63)
                }
            }
            WindowControlButtonKind::Close => {
                if hovered {
                    if scale < 128 {
                        lerp_color(0xFFE0_A197, 0xFFCF_796A, scale * 255 / 128)
                    } else {
                        lerp_color(0xFFCF_796A, 0xFFD5_4F36, (scale - 128) * 255 / 127)
                    }
                } else if scale < 115 {
                    lerp_color(0x80FF_FFFF, 0x4DFF_FFFF, scale * 255 / 115)
                } else if scale < 128 {
                    lerp_color(0x4DFF_FFFF, 0x1A00_0000, (scale - 115) * 255 / 13)
                } else if scale < 192 {
                    0x1A00_0000
                } else {
                    lerp_color(0x1A00_0000, 0x80FF_FFFF, (scale - 192) * 255 / 63)
                }
            }
        };
        surface.blend_rect(
            Rect::new(bounds.x, bounds.y + row as i32, bounds.width, 1),
            color,
        );
    }
    surface.blend_rect(Rect::new(bounds.x, bounds.y, bounds.width, 1), 0x60FF_FFFF);
    surface.blend_rect(
        Rect::new(
            bounds.x,
            bounds.y + bounds.height.saturating_sub(1) as i32,
            bounds.width,
            1,
        ),
        0x4D00_0000,
    );
}

pub fn menu_surface(surface: &mut Surface, bounds: Rect) {
    let shadow = Rect::new(bounds.x + 2, bounds.y + 2, bounds.width, bounds.height);
    surface.blend_rounded_rect(shadow, 3, 0x8000_0000);
    surface.fill_rect(
        bounds.x,
        bounds.y,
        bounds.width,
        bounds.height,
        ELEMENT_SURFACE,
    );
    surface.blend_rounded_rect(bounds, 3, 0x6000_0000);
    surface.blend_rect(Rect::new(bounds.x, bounds.y, bounds.width, 1), 0xA0FF_FFFF);
    surface.blend_rect(
        Rect::new(
            bounds.x,
            bounds.y + bounds.height.saturating_sub(1) as i32,
            bounds.width,
            1,
        ),
        0x80FF_FFFF,
    );
    surface.blend_rect(
        Rect::new(
            bounds.x + 28,
            bounds.y + 2,
            2,
            bounds.height.saturating_sub(4),
        ),
        0x2600_0000,
    );
}

pub fn menu_item(surface: &mut Surface, bounds: Rect, hovered: bool) {
    if hovered {
        surface.blend_rounded_rect(bounds, 3, 0xCCFF_FFFF);
        surface.blend_rect(bounds, 0xAA_DD_FA);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn glass_backdrop_blurs_tints_and_saturates() {
        let mut backdrop = Surface::new(32, 32);
        backdrop.fill_rect(0, 0, 16, 32, 0xFFFF_FFFF);
        backdrop.fill_rect(16, 0, 16, 32, 0xFF00_0000);
        let glass = glass_backdrop(&backdrop, 0x20_40A0FF, 64);

        assert_ne!(glass.pixel(15, 0), backdrop.pixel(15, 0));
        assert_ne!(glass.pixel(16, 0), backdrop.pixel(16, 0));
        assert_ne!(glass.pixel(15, 0), glass.pixel(16, 0));
    }

    #[test]
    fn shadow_and_rounded_window_are_composed() {
        let mut surface = Surface::new(48, 48);
        let bounds = Rect::new(8, 8, 32, 24);
        shadow_rect(&mut surface, bounds, 4);
        rounded_window(&mut surface, bounds, 6, 0xE8F4_F9FD);

        assert_ne!(surface.pixel(7, 8), Some(0));
        assert_ne!(surface.pixel(8, 8), Some(0));
        assert_eq!(
            surface.pixel(bounds.x as u32, bounds.y as u32),
            Some(0xB4FF_FFFF)
        );
        assert_ne!(
            surface.pixel(bounds.x as u32 + 31, bounds.y as u32 + 1),
            Some(0xB4FF_FFFF)
        );
    }
}
